  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
in vec4 color;
in vec2 uv0;
layout(std140) uniform Constant {
  vec4 brighterColor;
  vec4 middleColor;
  vec4 darkerColor;
  vec2 noiseScale;
  float spread;
  float fireHeight;
  float fireIntensity;
  float fireSpeed;
  float softness;
  float sideFade;
  float bottomFade;
  float flipY;
};
float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}
float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}
float fbm(vec2 p) {
  float v = 0.0;
  float amp = 0.52;
  for (int i = 0; i < 5; i++) {
    v += amp * noise(p);
    p *= 2.04;
    amp *= 0.5;
  }
  return v;
}
float edge(float threshold, float value) {
  float s = max(softness, 0.0001);
  return smoothstep(threshold - s, threshold + s, value);
}
vec4 frag () {
  float y = flipY > 0.5 ? 1.0 - uv0.y : uv0.y;
  float time = cc_time.x * fireSpeed;
  float safeSpread = max(spread, 0.05);
  vec2 centered = vec2((uv0.x - 0.5) / safeSpread, y * 0.72);
  float compactMask = 1.0 - smoothstep(0.36, 1.05, length(centered));
  float n1 = fbm(vec2(uv0.x * noiseScale.x, y * noiseScale.y - time));
  float n2 = fbm(vec2(uv0.x * noiseScale.x * 1.85 + 14.7, y * noiseScale.y * 1.55 - time * 1.34));
  float flameNoise = clamp(n1 * 0.64 + n2 * 0.48, 0.0, 1.0);
  float height = max(fireHeight, 0.1);
  float gradient = 1.0 - y / height;
  gradient += compactMask * 0.26;
  gradient -= smoothstep(safeSpread, safeSpread + 0.48, length(uv0 + vec2(-0.5, -0.5)) / safeSpread) * 0.22;
  float flame = edge(flameNoise, gradient);
  float mid = edge(flameNoise, gradient - 0.2);
  float hot = edge(flameNoise, gradient - 0.4);
  vec3 rgb = mix(brighterColor.rgb, darkerColor.rgb, clamp(flame - mid, 0.0, 1.0));
  rgb = mix(rgb, middleColor.rgb, clamp(mid - hot, 0.0, 1.0));
  rgb = mix(rgb, brighterColor.rgb, hot);
  float fadeSide = smoothstep(0.0, sideFade, uv0.x) * (1.0 - smoothstep(1.0 - sideFade, 1.0, uv0.x));
  float fadeBottom = smoothstep(0.0, max(bottomFade, 0.0001), y);
  float fadeTop = 1.0 - smoothstep(0.88, 1.0, y);
  float alpha = flame * fireIntensity * fadeSide * max(fadeBottom, 1.0 - step(0.001, bottomFade)) * fadeTop * color.a;
  vec4 outColor = vec4(rgb * color.rgb, alpha);
  return outColor;
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

